body [style*="opacity"]{opacity:1!important}
.ds-split { position: relative; display: flex; height: 168px;
  border: 1px solid var(--line); border-radius: var(--radius-lg); overflow: hidden; }
.ds-split > .ds-pane { padding: var(--space-3); color: var(--fg-3);
  font: var(--text-sm)/var(--leading-snug) var(--font-sans); }
.ds-pane-a { width: 180px; background: var(--panel-solid); }
.ds-pane-b { flex: 1; background: var(--sunken); }
.ds-col-handle { position: absolute; top: 0; bottom: 0; left: 176px; width: 7px;
  cursor: col-resize; }
.ds-col-handle::after { top: 0; bottom: 0; left: 3px; width: 1px; }
.ds-stack { display: flex; flex-direction: column; height: 168px;
  border: 1px solid var(--line); border-radius: var(--radius-lg); overflow: hidden; }
.ds-row-handle { position: relative; width: 100%; height: 7px; flex: none;
  margin: -3px 0; cursor: row-resize; }
.ds-row-handle::after { top: 3px; right: 0; left: 0; height: 1px; }
.ds-hovered .panel-resize-handle::after { background: var(--line-strong); }
